import os, re, json

# Load current grids again after receiving new demo
def load_grids():
    d = os.environ['RLM_SESSION_DIR']
    session_file = os.path.join(os.path.dirname(d), 'sessions', os.path.basename(d) + '.jsonl')
    t = open(session_file).read().replace('\\n', '\n')

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_str = t[m.end() : m.end()+h*w]
        rows = [rows_str[i:i+w] for i in range(0, h*w, w)]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

