def get_run_structure(grid):
    """Get the run-length encoding structure for cells belonging to blocks"""
    h, w = len(grid), len(grid[0])

    # Find which cells belong to any block
    cells_in_blocks = {}
    for i in range(h-1):
        for j in range(w-1):
            for dr in range(2):
                for dc in range(2):
                    r, c = i+dr, j+dc
                    if r not in cells_in_blocks:
                        cells_in_blocks[r] = []
                    cells_in_blocks[r].append(c)

    def compress_runs(cells):
        if not cells:
            return []
        sorted_cells = sorted(set(cells))
        runs = []
        start = sorted_cells[0]
        prev = sorted_cells[0]
        for cell in sorted_cells[1:]:
            if cell == prev + 1:
                prev = cell
            else:
                runs.append((start, prev))
                start = cell
                prev = cell
        runs.append((start, prev))
        return runs

    result = {}
    for r, cells in cells_in_blocks.items():
        result[r] = compress_runs(cells)
    return result

